/* Imagens embutidas (logo e fotos). Para trocar, use a pasta fotos/ */
window.IMG={"civic-frente": "data:image/jpeg;base64,", "civic-interior": "data:image/jpeg;base64,", "civic-tras": "data:image/jpeg;base64,", "feirao": "data:image/png;base64,", "hb20-frente": "data:image/jpeg;base64,", "hb20-interior": "data:image/jpeg;base64,", "hb20-tras": "data:image/jpeg;base64,", "logo": "data:image/png;base64,", "s10-frente": "data:image/jpeg;base64,", "s10-interior": "data:image/jpeg;base64,", "s10-tras": "data:image/jpeg;base64,", "sandero-frente": "data:image/jpeg;base64,", "sandero-interior": "data:image/jpeg;base64,", "sandero-tras": "data:image/jpeg;base64,"};
'use strict';
// ===== CONFIG: troque pelos dados reais =====
const WHATS='5521967619755', TEL='21 96761-9755';
const cars=[
 {id:'hb20',n:'Hyundai HB20 Style',a:2014,k:null,p:44900,f:56998,d:'1.6 completo · câmbio manual'},
 {id:'s10',n:'Chevrolet S10 LTZ',a:2013,k:null,p:69900,f:86388,d:'Completa · bancos em couro · câmbio manual'},
 {id:'sandero',n:'Renault Sandero Stepway',a:2020,k:130957,p:45000,f:58912,d:'Completo · com GNV · carro lindo'},
 {id:'civic',n:'Honda Civic LXS',a:2008,k:134857,p:null,f:null,d:'Completo · câmbio automático · bancos em couro',o:'Mega Feirão'}];
const $=id=>document.getElementById(id), brl=n=>n.toLocaleString('pt-BR',{style:'currency',currency:'BRL',maximumFractionDigits:0});
const ph=k=>`src="fotos/${k}.jpg" onerror="this.onerror=null;this.src=IMG['${k}']"`;
const wa=t=>`https://wa.me/${WHATS}?text=${encodeURIComponent(t)}`;
const page=document.body.dataset.page;
// Layout compartilhado
const links=[['index.html','Início','home'],['estoque.html','Estoque','estoque'],['financiamento.html','Financiamento','financiamento'],['venda.html','Venda o seu','venda'],['visita.html','Visita','visita'],['sobre.html','Sobre','sobre'],['contato.html','Contato','contato']];
$('hdr').outerHTML=`<header class="${page==='home'?'tr':''}"><a class="logo" href="index.html"><img src="${IMG.logo}" alt="Revenda Car"></a>
<button class="menu" aria-expanded="false" aria-controls="nav">Menu</button>
<nav id="nav" aria-label="Principal">${links.map(l=>`<a href="${l[0]}" class="${l[2]===page?'on':''}">${l[1]}</a>`).join('')}</nav>
<a class="btn sm" data-wa href="#">WhatsApp</a></header>`;
$('ftr').outerHTML=`<footer><div class="cols"><div><img src="${IMG.logo}" alt="Revenda Car"><p>Seminovos completos, revisados e abaixo da FIPE.</p></div>
<div><b>Páginas</b>${links.map(l=>`<a href="${l[0]}">${l[1]}</a>`).join('')}</div>
<div><b>Fale conosco</b><a data-wa href="#">WhatsApp ${TEL}</a><a href="https://www.instagram.com/revendacar.ofc/" target="_blank" rel="noopener">Instagram @revendacar.ofc</a></div></div>
<p class="legal">© Revenda Car. Valores e condições sujeitos a alteração sem aviso. Consulte disponibilidade.</p></footer>
<a class="wafab" data-wa href="#">WhatsApp</a>`;
document.querySelectorAll('[data-wa]').forEach(a=>{a.href=wa('Olá! Vim pelo site da Revenda Car.');a.target='_blank';a.rel='noopener'});
document.querySelectorAll('img[data-i]').forEach(i=>i.src=IMG[i.dataset.i]);
const mb=document.querySelector('.menu');mb.onclick=()=>{const o=$('nav').classList.toggle('open');mb.setAttribute('aria-expanded',o)};

const card=c=>`<button class="card" data-id="${c.id}" aria-label="Ver ${c.n}">${c.o?`<span class="tag">${c.o}</span>`:c.f?'<span class="tag">Abaixo da FIPE</span>':''}
<img ${ph(c.id+'-frente')} alt="${c.n}" loading="lazy"><div class="in"><h3>${c.n}</h3>
<small>${c.a}${c.k?' · '+c.k.toLocaleString('pt-BR')+' km':''} · ${c.d}</small>
${c.f?`<span class="fipe">FIPE ${brl(c.f)}</span>`:''}<span class="price">${c.p?brl(c.p):'Consulte'}</span></div></button>`;

// Home
if(page==='home'){
 $('grid').innerHTML=cars.map(card).join('');
 $('grid').onclick=e=>{if(e.target.closest('.card'))location.href='estoque.html'};
const hs=[['s10','S10 LTZ','Chevrolet · 2013'],['civic','Civic LXS','Honda · 2008'],['hb20','HB20 Style','Hyundai · 2014'],['sandero','Stepway','Renault · 2020']];
 let i=0,tm;const set=n=>{i=n;const [id,t,sub]=hs[n],c=cars.find(x=>x.id===id);
  hImg.onerror=()=>{hImg.onerror=null;hImg.src=IMG[id+'-frente']};hImg.src=`fotos/${id}-hero.jpg`;hImg.classList.remove('in');void hImg.offsetWidth;hImg.classList.add('in');
  hKick.textContent='SELEÇÃO REVENDA CAR';hTitle.textContent=t;hSub.textContent=sub.toUpperCase()+' · '+c.d.toUpperCase();
  hPrice.textContent=c.p?`Por ${brl(c.p)}${c.f?' · FIPE '+brl(c.f):''}`:'Consulte condições do Mega Feirão';
  [...dots.children].forEach((d,k)=>d.setAttribute('aria-current',k===n))};
 const hImg=$('hImg'),hKick=$('hKick'),hTitle=$('hTitle'),hSub=$('hSub'),hPrice=$('hPrice'),dots=$('dots');
 dots.innerHTML=hs.map((_,k)=>`<button aria-label="Destaque ${k+1}"></button>`).join('');
 dots.onclick=e=>{const k=[...dots.children].indexOf(e.target.closest('button'));if(k>=0){set(k);clearInterval(tm)}};
 set(0);if(!matchMedia('(prefers-reduced-motion:reduce)').matches)tm=setInterval(()=>set((i+1)%hs.length),6000);
}
// Estoque
if(page==='estoque'){
 const tipos={t:'Todos',o:'Abaixo da FIPE',v:'Com km informado'};let f='t';
 const draw=()=>{const s=$('sort').value;
  const l=cars.filter(c=>f==='t'||(f==='o'&&c.f)||(f==='v'&&c.k)).sort((a,b)=>s==='p'?(a.p||1e9)-(b.p||1e9):s==='P'?(b.p||0)-(a.p||0):s==='a'?b.a-a.a:(a.k||1e9)-(b.k||1e9));
  $('count').textContent=l.length+(l.length===1?' veículo':' veículos');$('grid').innerHTML=l.map(card).join('')};
 $('tabs').innerHTML=Object.entries(tipos).map(([k,v])=>`<button data-k="${k}" aria-pressed="${k===f}">${v}</button>`).join('');
 $('tabs').onclick=e=>{const b=e.target.closest('button');if(!b)return;f=b.dataset.k;[...$('tabs').children].forEach(x=>x.setAttribute('aria-pressed',x===b));draw()};
 $('sort').onchange=draw;draw();
 const open=c=>{const im=['frente','tras','interior'];
  $('dbody').innerHTML=`<div class="dg"><div><div class="main"><img id="big" ${ph(c.id+'-frente')} alt="${c.n}"></div>
  <div class="thumbs">${im.map((n,i)=>`<img ${ph(c.id+'-'+n)} data-n="${n}" class="${i?'':'on'}" alt="Foto ${n}">`).join('')}</div></div>
  <div class="side"><h3 style="font-size:40px">${c.n}</h3><small>${c.a}${c.k?' · '+c.k.toLocaleString('pt-BR')+' km':''}</small><p>${c.d}</p>
  ${c.f?`<span class="fipe">FIPE ${brl(c.f)}</span>`:''}<span class="price">${c.p?brl(c.p):'Consulte'}</span>
  <a class="btn wa" target="_blank" rel="noopener" href="${wa('Olá! Tenho interesse no '+c.n+' '+c.a)}">Chamar no WhatsApp</a></div></div>`;
  $('dbody').querySelector('.thumbs').onclick=e=>{const t=e.target.closest('img');if(!t)return;$('big').src=t.src;[...t.parentNode.children].forEach(x=>x.classList.toggle('on',x===t))};
  $('dlg').showModal()};
 $('grid').onclick=e=>{const b=e.target.closest('.card');if(b)open(cars.find(c=>c.id===b.dataset.id))};
 $('dx').onclick=()=>$('dlg').close();$('dlg').onclick=e=>{if(e.target===$('dlg'))$('dlg').close()};
}
// Contato
if(page==='contato'){
 $('carroSel').innerHTML='<option>Ainda não decidi</option>'+cars.map(c=>`<option>${c.n} ${c.a}</option>`).join('');
 $('form').onsubmit=e=>{e.preventDefault();const d=new FormData(e.target);open(wa(`Olá! Sou ${d.get('nome')}. Interesse: ${d.get('carro')}. ${d.get('msg')||''}`),'_blank','noopener')};
}
// Simulador (página inicial)
if($('v')){const v=$('v'),en=$('e'),pz=$('p'),sim=()=>{const val=+v.value,ent=+en.value,n=+pz.value,i=.016,par=val*(1-ent/100)*i/(1-Math.pow(1+i,-n));
 $('ov').textContent=brl(val);$('oe').textContent=ent+'% ('+brl(val*ent/100)+')';$('op').textContent=n+' meses';$('parc').textContent=brl(par)+'/mês'};
 [v,en,pz].forEach(x=>x.oninput=sim);sim();}

const hd=document.querySelector('header');if(hd.classList.contains('tr')){const t=()=>hd.classList.toggle('solid',scrollY>60);addEventListener('scroll',t,{passive:true});t()}

// Selects de carros e formulários genéricos -> WhatsApp
document.querySelectorAll('select[data-cars]').forEach(s=>s.innerHTML='<option>Ainda não decidi</option>'+cars.map(c=>`<option>${c.n} ${c.a}</option>`).join(''));
document.querySelectorAll('form[data-wa-form]').forEach(f=>f.onsubmit=e=>{e.preventDefault();
 const t=[...new FormData(f)].filter(([,v])=>v).map(([k,v])=>`${k}: ${v}`).join('\n');
 open(wa(`Olá! ${f.dataset.waForm}.\n${t}`),'_blank','noopener')});
